quadriceps","gluteal"],"secondary_muscles":["adductors","lower-back","abs"],"aliases":["杠铃深蹲","背蹲"],"description":"主要训练大腿、臀部。","instructions":["先调整杠铃和保护杆高度，确认卡箍、架位和保护条件合适。","将杠铃稳定放在上背部，握稳后出架，双脚站稳。","保持躯干稳定，屈髋屈膝下蹲到可控制的深度，再蹬地站起。","完成后向前回架；不熟悉架位或保护设置时先使用高脚杯深蹲。"],"equipment_evidence":"IMG_3014","weight_note":"记录杠铃杆与两侧片的总重。"},{"id":"dumbbell-romanian-deadlift","name":"哑铃罗马尼亚硬拉","english_name":"dumbbell Romanian deadlift","equipment":"哑铃","load_mode":"external","muscles":["大腿后侧、臀部"],"primary_muscles":["hamstring","gluteal"],"secondary_muscles":["lower-back","forearm"],"aliases":["哑铃RDL","罗马尼亚硬拉"],"description":"主要训练大腿后侧、臀部。","instructions":["双手持哑铃放在大腿前方，膝盖保持轻微弯曲。","将臀部向后送，哑铃贴近腿部下降，躯干保持稳定。","下降到能够控制且大腿后侧有拉伸感的位置，再伸髋站起；不以触地为目标。"],"equipment_evidence":"用户确认有哑铃","weight_note":"每只哑铃重量；高脚杯深蹲记录单只总重。"},{"id":"prone-leg-curl","name":"俯卧腿弯举","english_name":"prone leg curl","equipment":"俯卧腿弯举机","load_mode":"external","muscles":["大腿后侧"],"primary_muscles":["hamstring"],"secondary_muscles":["calves"],"aliases":["俯卧勾腿","腿弯举"],"description":"主要训练大腿后侧。","instructions":["调整腿垫使其位于脚踝后侧附近，让膝关节与机器转轴大致对齐。","俯卧并握稳把手，保持髋部贴垫，通过屈膝带动滚垫。","在可控制的范围内慢慢伸膝回放，避免抬起髋部借力。"],"equipment_evidence":"IMG_3006 / IMG_3007","weight_note":"记录器械显示重量。"},{"id":"machine-leg-extension","name":"器械腿屈伸","english_name":"leg extension","equipment":"腿屈伸机","load_mode":"external","muscles":["大腿前侧"],"primary_muscles":["quadriceps"],"secondary_muscles":[],"aliases":["腿伸展","坐姿腿屈伸"],"description":"主要训练大腿前侧。","instructions":["调整靠背，让膝关节与器械转轴大致对齐，滚垫放在小腿前侧靠近脚踝处。","握稳把手，背部贴住靠垫，伸膝抬起滚垫。","在可控制的范围内缓慢屈膝回放，避免靠摆动身体甩起重量。"],"equipment_evidence":"IMG_3008","weight_note":"记录器械显示重量。"},{"id":"dumbbell-standing-calf-raise","name":"哑铃站姿提踵","english_name":"standing dumbbell calf raise","equipment":"哑铃","load_mode":"external","muscles":["小腿"],"primary_muscles":["calves"],"secondary_muscles":[],"aliases":["站姿提踵","小腿提踵"],"description":"主要训练小腿。","instructions":["在平稳地面站立，手持哑铃；需要时用另一只手轻扶稳固支撑物。","保持身体稳定，抬起脚跟，用前脚掌支撑身体。","缓慢落下脚跟，避免通过弹跳完成动作。"],"equipment_evidence":"用户确认有哑铃","weight_note":"每只哑铃重量；高脚杯深蹲记录单只总重。"},{"id":"machine-abdominal-crunch","name":"器械卷腹","english_name":"machine abdominal crunch","equipment":"卷腹机","load_mode":"external","muscles":["腹部"],"primary_muscles":["abs"],"secondary_muscles":[],"aliases":["卷腹机","坐姿卷腹"],"description":"主要训练腹部。","instructions":["调整座椅，使上背部贴住支撑垫，双手握稳把手。","通过躯干屈曲向前卷起，避免只用手臂拉动把手。","控制躯干回到起始位置，不让配重片突然落下。"],"equipment_evidence":"IMG_3004","weight_note":"记录器械显示重量。"},{"id":"dumbbell-biceps-curl","name":"普通哑铃弯举","muscles":["肱二头肌"],"equipment":"哑铃","load_mode":"external","english_name":"Dumbbell biceps curl","aliases":[],"primary_muscles":["biceps"],"secondary_muscles":["forearm"],"description":"主要训练二头肌，家庭训练使用。","instructions":["站稳，双手持哑铃，保持上臂大致稳定。","弯曲肘部抬起哑铃，避免摆动躯干。","控制下放，使用肘部舒适的幅度。"],"equipment_evidence":"用户确认家庭有哑铃和可调训练凳","weight_note":"记录每只哑铃重量；单只哑铃双手过顶臂屈伸记录该只哑铃总重。"},{"id":"dumbbell-overhead-triceps-extension","name":"哑铃过顶臂屈伸","muscles":["肱三头肌"],"equipment":"哑铃","load_mode":"external","english_name":"Dumbbell overhead triceps extension","aliases":[],"primary_muscles":["triceps"],"secondary_muscles":[],"description":"主要训练三头肌；双手持一只哑铃时记录该只哑铃总重。","instructions":["坐姿或站姿稳定躯干，双手握住一只哑铃，或使用舒适的单臂方式。","在肩肘舒适的幅度内屈肘下放，再伸肘抬起。","避免明显挺腰，出现肩肘不适时缩小幅度或调整动作。"],"equipment_evidence":"用户确认家庭有哑铃和可调训练凳","weight_note":"记录每只哑铃重量；单只哑铃双手过顶臂屈伸记录该只哑铃总重。"},{"id":"dumbbell-reverse-fly","name":"哑铃反向飞鸟","muscles":["肩后束","背部"],"equipment":"哑铃","load_mode":"external","english_name":"Dumbbell reverse fly","aliases":[],"primary_muscles":["deltoids"],"secondary_muscles":["upper-back"],"description":"主要训练三角肌后束，可采用胸托方式减少躯干代偿。","instructions":["俯身或胸托训练凳，保持躯干稳定，肘部轻微弯曲。","以可控重量向两侧打开双臂，感受肩后侧发力。","允许肩胛自然运动，避免甩动、突然抬肩和颈部明显紧绷。"],"equipment_evidence":"用户确认家庭有哑铃和可调训练凳","weight_note":"记录每只哑铃重量；单只哑铃双手过顶臂屈伸记录该只哑铃总重。"},{"id":"dumbbell-lying-triceps-extension","name":"哑铃仰卧臂屈伸","muscles":["肱三头肌"],"equipment":"哑铃、训练凳","load_mode":"external","english_name":"Lying dumbbell triceps extension","aliases":[],"primary_muscles":["triceps"],"secondary_muscles":[],"description":"公司漏做绳索下压时可按原组数在家替代，不额外增加组数。","instructions":["仰卧训练凳，双手持哑铃，上臂保持相对稳定。","在肘部舒适范围内屈肘下放，再控制伸肘。","使用轻到中等重量，避免强行追求深度。"],"equipment_evidence":"用户确认家庭有哑铃和可调训练凳","weight_note":"记录每只哑铃重量；单只哑铃双手过顶臂屈伸记录该只哑铃总重。"},{"id":"dumbbell-fly","name":"哑铃飞鸟","muscles":["胸部"],"equipment":"哑铃、训练凳","load_mode":"external","tracking":"reps","training_type":"strength","english_name":"Dumbbell fly","aliases":["平板哑铃飞鸟"],"primary_muscles":["chest"],"secondary_muscles":["deltoids"],"description":"仰卧训练凳，以可控重量进行胸部飞鸟。","instructions":["仰卧稳住躯干，肘部保持微屈。","在肩部舒适范围内缓慢打开双臂，再向上合拢。","避免为追求幅度过度下探。"],"equipment_evidence":"用户已确认家庭有哑铃和可调训练凳","weight_note":"记录每只哑铃重量。"},{"id":"kneeling-cable-crunch","name":"跪姿绳索卷腹","english_name":"Kneeling Cable Crunch","equipment":"龙门架","load_mode":"external","tracking":"reps","training_type":"strength","muscles":["腹部"],"primary_muscles":["abs"],"secondary_muscles":[],"aliases":[],"description":"收缩腹部，让肋骨向骨盆靠近。","instructions":["高位滑轮接绳索，跪稳，双手将绳索保持在头侧。","呼气卷起躯干，避免只用髋部折叠或手臂下拉。","控制回到起始位，保持绳索张力。"],"equipment_evidence":"用户确认有龙门架、哑铃、训练凳和瑜伽垫","weight_note":"记录当前滑轮器械显示重量；首次用轻重量试练。"},{"id":"cable-pallof-press-bilateral","name":"绳索抗旋转推（双侧）","english_name":"Bilateral Pallof Press","equipment":"龙门架","load_mode":"external","tracking":"reps","training_type":"strength","muscles":["腹部"],"primary_muscles":["abs","obliques"],"secondary_muscles":[],"aliases":[],"description":"每组左右各做一次；次数栏记录每侧次数，左右完成后再勾选。","instructions":["滑轮约胸口高度，侧身站立，双手将手柄握于胸前。","向前推出并停1–2秒，胸口和骨盆保持朝前。","每轮左右各10–12次，换侧约15秒；两侧完成后勾选一组，再休息60秒。"],"equipment_evidence":"用户确认有龙门架、哑铃、训练凳和瑜伽垫","weight_note":"记录器械显示重量；次数为每侧次数，一组包含左右两侧。"},{"id":"floor-crunch","name":"瑜伽垫卷腹","english_name":"Floor Crunch","equipment":"瑜伽垫","load_mode":"bodyweight","tracking":"reps","training_type":"strength","muscles":["腹部"],"primary_muscles":["abs"],"secondary_muscles":[],"aliases":[],"description":"肩胛骨稍离地，缓慢下放，不拉脖子。","instructions":["仰卧屈膝，脚掌落地，双手放胸前。","呼气使肋骨靠近骨盆，肩胛骨稍离地即可。","控制下放，不靠甩动或拉脖子完成。"],"equipment_evidence":"用户确认有龙门架、哑铃、训练凳和瑜伽垫","weight_note":""},{"id":"forearm-plank","name":"前臂平板支撑","english_name":"Forearm Plank","equipment":"瑜伽垫","load_mode":"bodyweight","tracking":"duration","training_type":"strength","muscles":["腹部"],"primary_muscles":["abs"],"secondary_muscles":[],"aliases":[],"description":"以保持躯干稳定为标准，每组20–40秒。","instructions":["前臂撑地，肘部大致位于肩下。","肋骨与骨盆保持稳定，正常呼吸。","避免塌腰、抬臀；姿势开始失控时结束本组。"],"equipment_evidence":"用户确认有龙门架、哑铃、训练凳和瑜伽垫","weight_note":""},{"id":"dumbbell-seated-calf-raise","name":"坐姿哑铃提踵","english_name":"Seated Dumbbell Calf Raise","equipment":"哑铃、训练凳","load_mode":"external","tracking":"reps","training_type":"strength","muscles":["小腿"],"primary_muscles":["calves"],"secondary_muscles":[],"aliases":[],"description":"坐稳后抬起脚跟，缓慢下放，偏重比目鱼肌。","instructions":["坐在稳固凳上，双脚落地，膝盖约90度。","将哑铃稳放在大腿靠近膝盖处，手扶住哑铃。","用前脚掌支撑抬起脚跟，再缓慢落下，避免弹动。"],"equipment_evidence":"用户确认有龙门架、哑铃、训练凳和瑜伽垫","weight_note":"记录两腿上哑铃的合计重量；双脚同时完成。"},{"id":"posture-forearm-wall-slide","name":"面墙前臂滑手","english_name":"Forearm Wall Slide","equipment":"墙面","load_mode":"bodyweight","tracking":"reps","training_type":"mobility","muscles":["serratus","trapezius"],"primary_muscles":["serratus","trapezius"],"secondary_muscles":[],"description":"日常体态与活动控制练习。动作保持舒适、正常呼吸；不强行压肩或追求极限幅度。","instructions":["面对墙站立，前臂轻贴墙，肋骨自然收住。","沿墙缓慢向上滑手，允许肩胛自然上旋，不强行压肩。","在舒适范围内缓慢返回，完成8–12次。"],"weight_note":""},{"id":"posture-thoracic-extension","name":"坐姿胸椎伸展","english_name":"Seated Thoracic Extension","equipment":"椅子","load_mode":"bodyweight","tracking":"reps","training_type":"mobility","muscles":["upper-back"],"primary_muscles":["upper-back"],"secondary_muscles":[],"description":"日常体态与活动控制练习。动作保持舒适、正常呼吸；不强行压肩或追求极限幅度。","instructions":["坐稳，椅背上缘支撑胸椎附近，双手轻托后脑。","轻轻向后伸展上背，避免用腰部大幅后仰代偿。","正常呼吸，回到起始姿势；完成6–8次。"],"weight_note":""},{"id":"posture-doorway-left","name":"门框胸肌拉伸 · 左侧","english_name":"Doorway Chest Stretch Left","equipment":"门框","load_mode":"bodyweight","tracking":"duration","training_type":"mobility","muscles":["chest"],"primary_muscles":["chest"],"secondary_muscles":[],"description":"日常体态与活动控制练习。动作保持舒适、正常呼吸；不强行压肩或追求极限幅度。","instructions":["左前臂轻扶门框，手肘高度以舒适为准。","身体缓慢向前，至左胸前侧有轻柔牵拉感，不顶肩、不憋气。","保持20–30秒后放松；完成2组。"],"weight_note":""},{"id":"posture-doorway-right","name":"门框胸肌拉伸 · 右侧","english_name":"Doorway Chest Stretch Right","equipment":"门框","load_mode":"bodyweight","tracking":"duration","training_type":"mobility","muscles":["chest"],"primary_muscles":["chest"],"secondary_muscles":[],"description":"日常体态与活动控制练习。动作保持舒适、正常呼吸；不强行压肩或追求极限幅度。","instructions":["右前臂轻扶门框，手肘高度以舒适为准。","身体缓慢向前，至右胸前侧有轻柔牵拉感，不顶肩、不憋气。","保持20–30秒后放松；完成2组。"],"weight_note":""},{"id":"posture-chin-tuck","name":"下巴轻收（可选）","english_name":"Chin Tuck","equipment":"自重","load_mode":"bodyweight","tracking":"reps","training_type":"mobility","muscles":[],"primary_muscles":[],"secondary_muscles":[],"description":"日常体态与活动控制练习。动作保持舒适、正常呼吸；不强行压肩或追求极限幅度。","instructions":["坐姿或站姿自然，目视前方。","下巴轻轻向后收，避免低头或用力挤压颈部。","每次保持约3秒后放松，完成8–10次；不适时跳过。"],"weight_note":""},{"id":"posture-chest-supported-y-raise","name":"胸托 Y Raise","english_name":"Chest Supported Y Raise","equipment":"哑铃、上斜凳","load_mode":"external","tracking":"reps","training_type":"mobility","muscles":["trapezius"],"primary_muscles":["trapezius"],"secondary_muscles":[],"description":"日常体态与活动控制练习。动作保持舒适、正常呼吸；不强行压肩或追求极限幅度。","instructions":["凳子调至30–45°，胸口贴凳，拇指大致朝上。","双臂向斜前上方伸远，允许肩胛自然上旋和适度抬升。","避免突然抬肩、颈部紧绷与挺腰；2组，每组10–12次，保留充足余力。"],"weight_note":"可先徒手熟悉动作；独立体态练习，不计入主计划72组。"}],"templates":[{"template":{"id":"guided-upper-a","name":"A · 公司｜胸·肩·三头","description":"3个动作，每个3个正式组；热身另算。","notes":"333计划：公司与家庭各9个正式组，一轮72组。多数正式组保留约2次余力，按实际完成次数记录。首次按逐组预设开始，之后沿用本模板的实际表现；达到次数上限且动作稳定后，再增加可用的最小重量。热身默认休息60秒，复合动作120秒、必要时180秒；孤立动作按模板75或90秒。推肩70/70/60 lb各8次，下压80/80/70 lb各10次；较重组接近力竭时下调重量。卧推65 lb×8/8/8，重量沿用原记录口径；疲劳时次数可自然下降。","duration_min":20,"duration_max":30,"rotation_order":0,"exercises":[{"exercise_id":"barbell-bench-press","set_count":5,"unit":"lb","rest_seconds":120,"target_reps":8,"progression":"off","rep_min":6,"rep_max":10,"increment":null,"warmup